export const inventoryCountLines=amo.table('inventory_count_lines',{id:uuid('id').primaryKey(),operatorId:text('operator_id').notNull(),sessionId:text('session_id').notNull(),lotId:uuid('lot_id'),partNo:text('part_no').notNull(),serial:text('serial'),lotNo:text('lot_no'),binId:uuid('bin_id'),expectedQty:integer('expected_qty').notNull(),countedQty:integer('counted_qty'),varianceQty:integer('variance_qty'),discrepancyReason:text('discrepancy_reason'),status:text('status').notNull(),countedBy:text('counted_by'),countedAt:ts('counted_at'),reconciledBy:text('reconciled_by'),reconciledAt:ts('reconciled_at')});
