  async createForecast(p:Principal,b:z.infer<typeof forecastSchema>){await this.can(p,'requisition');if(b.horizonEnd<b.horizonStart)throw new DomainError('FORECAST_PERIOD','Forecast end must be after start',422);const calc=weightedDemand({maintenance:b.maintenance,historical:b.historical,reliability:b.reliability,fleet:b.fleet,safetyStock:b.safetyStock});const qty=b.overrideQty??calc;const id=randomUUID();const explanation={weighted:{maintenance:b.maintenance,historical:b.historical,reliability:b.reliability,fleet:b.fleet,safetyStock:b.safetyStock},calculated:calc,override:b.overrideQty};await this.db.db.insert(demandForecasts).values({id,operatorId:p.operatorId,partNo:b.partNo,station:b.station.toUpperCase(),horizonStart:b.horizonStart,horizonEnd:b.horizonEnd,maintenanceDemand:String(b.maintenance),historicalDemand:String(b.historical),reliabilityDemand:String(b.reliability),fleetDemand:String(b.fleet),safetyStock:String(b.safetyStock),forecastQty:String(qty),method:b.overrideQty===null?'WEIGHTED':'PLANNER_OVERRIDE',explanation,generatedBy:actorOf(p),generatedAt:new Date()});await this.auditRecord(p,'supply.forecast_generated','demand_forecast',id,explanation);return{id,forecastQty:qty}}
  async proposals(p:Principal){await this.can(p,'read');const ps=await this.db.db.select().from(replenishmentPolicies).where(and(eq(replenishmentPolicies.operatorId,p.operatorId),eq(replenishmentPolicies.active,true)));const result=[] as any[];for(const x of ps){const [on]=await this.db.db.select({q:stock.qty}).from(stock).where(and(eq(stock.operatorId,p.operatorId),eq(stock.partNo,x.partNo),eq(stock.location,x.station)));const rs=await this.db.db.execute<{q:string}>(sql`select coalesce(sum(qty),0)::text q from amo.reservations where operator_id=${p.operatorId} and part_no=${x.partNo} and location=${x.station} and status='RESERVED'`);const po=await this.db.db.execute<{q:string}>(sql`select coalesce(sum(qty-received_qty),0)::text q from amo.purchase_orders where operator_id=${p.operatorId} and part_no=${x.partNo} and station=${x.station} and status in ('ISSUED','PARTIALLY_RECEIVED')`);const [f]=await this.db.db.select().from(demandForecasts).where(and(eq(demandForecasts.operatorId,p.operatorId),eq(demandForecasts.partNo,x.partNo),eq(demandForecasts.station,x.station))).orderBy(desc(demandForecasts.generatedAt)).limit(1);const r=replenishmentProposal({onHand:on?.q??0,reserved:Number(rs.rows[0]?.q??0),inbound:Number(po.rows[0]?.q??0),forecast:Number(f?.forecastQty??0),policy:{minQty:x.minQty,maxQty:x.maxQty,reorderQty:x.reorderQty}});result.push({policy:x,onHand:on?.q??0,reserved:Number(rs.rows[0]?.q??0),inbound:Number(po.rows[0]?.q??0),forecast:Number(f?.forecastQty??0),...r})}return result}
