  @Post('fulfillment/:id/pack') pack(@CurrentPrincipal()p:Principal,@Param('id')id:string,@Body(new ZodPipe(packSchema))_b:Record<string,never>){return this.s.pack(p,id)}
  @Post('fulfillment/:id/ship') ship(@CurrentPrincipal()p:Principal,@Param('id')id:string,@Body(new ZodPipe(shipSchema))b:z.infer<typeof shipSchema>){return this.s.ship(p,id,b)}
  @Post('fulfillment/:id/cancel') cancelFulfillment(@CurrentPrincipal()p:Principal,@Param('id')id:string,@Body(new ZodPipe(reasonSchema))b:z.infer<typeof reasonSchema>){return this.s.cancelFulfillment(p,id,b)}
  @Post('fulfillment/:id/receive') receive(@CurrentPrincipal()p:Principal,@Param('id')id:string){return this.s.receiveFulfillment(p,id)}
  @Get('policies') policies(@CurrentPrincipal()p:Principal){return this.s.policies(p)}
  @Post('policies') policy(@CurrentPrincipal()p:Principal,@Body(new ZodPipe(policySchema))b:z.infer<typeof policySchema>){return this.s.setPolicy(p,b)}
  @Post('policies/:id/deactivate') deactivatePolicy(@CurrentPrincipal()p:Principal,@Param('id')id:string,@Body(new ZodPipe(reasonSchema))b:z.infer<typeof reasonSchema>){return this.s.deactivatePolicy(p,id,b)}
  @Get('forecasts') forecasts(@CurrentPrincipal()p:Principal){return this.s.forecasts(p)}
  @Post('forecasts') forecast(@CurrentPrincipal()p:Principal,@Body(new ZodPipe(forecastSchema))b:z.infer<typeof forecastSchema>){return this.s.createForecast(p,b)}
  @Get('replenishment') replenishment(@CurrentPrincipal()p:Principal){return this.s.proposals(p)}
  @Post('replenishment/:policyId/requisition') requisition(@CurrentPrincipal()p:Principal,@Param('policyId')id:string){return this.s.requisitionProposal(p,id)}
  @Get('consignments') consignments(@CurrentPrincipal()p:Principal){return this.s.consignments(p)}
  @Post('consignments') consignment(@CurrentPrincipal()p:Principal,@Body(new ZodPipe(consignmentSchema))b:z.infer<typeof consignmentSchema>){return this.s.createConsignment(p,b)}
  @Post('forecasts/derive') deriveForecast(@CurrentPrincipal()p:Principal,@Body(new ZodPipe(z.object({partNo:z.string().trim().min(2),station:z.string().trim().min(3).max(6),horizonStart:z.string().regex(/^\d{4}-\d{2}-\d{2}$/),horizonEnd:z.string().regex(/^\d{4}-\d{2}-\d{2}$/)})))b:{partNo:string;station:string;horizonStart:string;horizonEnd:string}){return this.s.deriveForecast(p,b.partNo,b.station,b.horizonStart,b.horizonEnd)}
  @Get('supplier-quality') quality(@CurrentPrincipal()p:Principal){return this.s.qualityEvents(p)}
  @Post('supplier-quality') recordQuality(@CurrentPrincipal()p:Principal,@Body(new ZodPipe(qualityEventSchema))b:z.infer<typeof qualityEventSchema>){return this.s.recordQualityEvent(p,b)}
  @Get('price-agreements') prices(@CurrentPrincipal()p:Principal){return this.s.priceAgreements(p)}
  @Post('price-agreements') price(@CurrentPrincipal()p:Principal,@Body(new ZodPipe(priceAgreementSchema))b:z.infer<typeof priceAgreementSchema>){return this.s.createPriceAgreement(p,b)}
  @Post('consignments/:id/deactivate') deactivateConsignment(@CurrentPrincipal()p:Principal,@Param('id')id:string,@Body(new ZodPipe(reasonSchema))b:z.infer<typeof reasonSchema>){return this.s.deactivateConsignment(p,id,b)}
  @Post('price-agreements/:id/deactivate') deactivatePrice(@CurrentPrincipal()p:Principal,@Param('id')id:string,@Body(new ZodPipe(reasonSchema))b:z.infer<typeof reasonSchema>){return this.s.deactivatePriceAgreement(p,id,b)}
